def transform(grid):
    if not grid or not grid[0]:
        return grid

    R, C = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(cell for row in grid for cell in row)
    bg = max(counts, key=counts.get)

    # Find positions of each non-bg value
    by_value = {}
    for r in range(R):
        for c in range(C):
            v = grid[r][c]
            if v != bg:
                if v not in by_value:
                    by_value[v] = []
                by_value[v].append((r, c))

    result = [row[:] for row in grid]

    # For each value appearing twice (rectangle pattern), fill UP-LEFT diagonal
    for v, positions in by_value.items():
        if len(positions) == 2:
            # Sort by column descending
            pairs = sorted(positions, key=lambda p: p[1], reverse=True)
            r1, c1 = pairs[0]
            r2, c2 = pairs[1]

            # Fill UP-LEFT from top-right position until boundary
            r, c = r1, c1
            while r > 0 and c > c2:
                r -= 1
                c -= 1
                if result[r][c] == bg:
                    result[r][c] = v

    # Find single-occurrence values (constant markers)
    for v, positions in by_value.items():
        if len(positions) == 1:
            r, c = positions[0]
            r, c = r + 1, c - 1
            while r < R and c >= 0 and result[r][c] == bg:
                result[r][c] = v
                r += 1
                c -= 1

    return result
